import jDialog from '@/component/dialog.vue';
export default {
	props: {
		// 是否显示弹窗
		isShowDialog: {
			type: Boolean,
			required: true,
			default() {
				return false;
			}
		}
	},
	data() {
		return {
			// isShowDialog: true
			username: '',
			userpwd: '',
			pwdType: 'password',
			isSubmiting: false
		};
	},
	created() {},
	methods: {
		// 输入账户
		inputUsername(e) {
			this.username = e.target.value;
		},
		// 输入密码
		inputPwd(e) {
			this.userpwd = e.target.value;
		},

		// 清空账户
		delUser() {
			this.username = '';
		},
		// 查看密码
		switchPwd() {
			this.pwdType = this.pwdType === 'text' ? 'password' : 'text';
		},
		// 注册
		registerEvt() {
			if(this.isSubmiting){
				return
			}
			const username = this.username,
				userpwd = this.userpwd;
			if (!username.trim()) {
				this.$common.toast('请输入账号');
				return;
			}
			if (!userpwd.trim()) {
				this.$common.toast('请输入密码');
				return;
			}
			
			const params = {
				userName: username,
				password: userpwd
			};
			this.isSubmiting = true;
			this.$api({
				url: '/user/register',
				data: params
			})
				.then(res => {
					this.closeDialog();
					this.$emit('addMemberSuccess', true);
				})
				.catch(e => {
					this.$common.toast(e.msg);
				})
				.finally(() => {
					this.isSubmiting = false;
				});
		},

		closeDialog() {
			this.username = '';
			this.userpwd = '';
			this.pwdType = 'password';
			this.$emit('closeDialog', false);
		}
	},
	components: { jDialog }
};
